package com.courtstory.app;

import android.content.Context;
import android.security.keystore.*;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import static com.courtstory.app.Domain.*;

final class ConnectClient {
    private static ConnectClient instance;
    static synchronized ConnectClient get(Context context){if(instance==null)instance=new ConnectClient(context.getApplicationContext());return instance;}
    final ExecutorService worker=Executors.newSingleThreadExecutor();
    final Context context;
    private JSONObject session,state=obj(),config=obj();
    volatile String status="Local-only. Signing in does not upload your library.";
    JSONArray connections=new JSONArray(),records=new JSONArray(),feedback=new JSONArray(),participants=new JSONArray(),notifications=new JSONArray();
    JSONObject notificationSettings=obj();
    private long recordCursor=0; private String connectionFingerprint="";
    private ConnectClient(Context context){this.context=context;try(InputStream in=context.getAssets().open("CourtConnectConfig.json")){config=new JSONObject(new String(readBytes(in),StandardCharsets.UTF_8));}catch(Exception ignored){}
        ConnectPush.configure(context,config);
        try{AtomicFile f=new AtomicFile(new File(context.getNoBackupFilesDir(),"connect-session.enc"));if(f.getBaseFile().exists()){byte[] data=f.readFully();Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(data,0,12)));session=new JSONObject(new String(c.doFinal(Arrays.copyOfRange(data,12,data.length)),StandardCharsets.UTF_8));loadState();}}catch(Exception e){session=null;status="Sign in again to Connect. Local sporting records are unchanged.";}
    }
    private SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);if(!s.containsAlias("CourtStoryConnect")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("CourtStoryConnect",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (SecretKey)s.getKey("CourtStoryConnect",null);}
    synchronized String account(){return session==null?"":object(session,"user").optString("id").toLowerCase(Locale.ROOT);}
    synchronized boolean signedIn(){return session!=null;}
    String linkHost(){return config.optString("link_host");}
    private AtomicFile stateFile(){return new AtomicFile(new File(context.getNoBackupFilesDir(),"connect-"+account()+".json"));}
    private void loadState()throws Exception{AtomicFile f=stateFile();state=f.getBaseFile().exists()?new JSONObject(new String(f.readFully(),StandardCharsets.UTF_8)):obj();}
    private void write(AtomicFile file,byte[] bytes)throws IOException{FileOutputStream out=null;try{out=file.startWrite();out.write(bytes);file.finishWrite(out);}catch(IOException e){if(out!=null)file.failWrite(out);throw e;}}
    private void persist()throws IOException{write(stateFile(),state.toString().getBytes(StandardCharsets.UTF_8));}
    private synchronized void saveSession(JSONObject value)throws Exception{String before=account();Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());byte[] encrypted=c.doFinal(value.toString().getBytes(StandardCharsets.UTF_8));ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(c.getIV());out.write(encrypted);write(new AtomicFile(new File(context.getNoBackupFilesDir(),"connect-session.enc")),out.toByteArray());session=value;if(!before.equals(account())){loadState();records=new JSONArray();feedback=new JSONArray();connections=new JSONArray();}}
    synchronized void signOut()throws Exception{if(signedIn()){JSONObject p=obj();put(p,"p_installation",installation());rpc("cs_unregister_device",p);}ConnectPush.disable(context);notifications=new JSONArray();notificationSettings=obj();new AtomicFile(new File(context.getNoBackupFilesDir(),"connect-session.enc")).delete();session=null;state=obj();records=new JSONArray();feedback=new JSONArray();connections=new JSONArray();status="Signed out. Local sporting records are unchanged.";}
    void deleteAccount()throws Exception{request("/functions/v1/delete-account","DELETE",null,true,true);stateFile().delete();ConnectPush.disable(context);new AtomicFile(new File(context.getNoBackupFilesDir(),"connect-session.enc")).delete();session=null;state=obj();records=new JSONArray();participants=new JSONArray();connections=new JSONArray();feedback=new JSONArray();notifications=new JSONArray();notificationSettings=obj();status="Connect account and cloud data deleted. Your local sporting library is unchanged.";}
    private static byte[] readBytes(InputStream input)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];for(int count;(count=input.read(buffer))!=-1;){if(out.size()+count>8*1024*1024)throw new IOException("Connect response exceeded the safe size limit.");out.write(buffer,0,count);}return out.toByteArray();}
    private Object request(String path,String method,JSONObject body,boolean auth,boolean retry)throws Exception{
        String base=config.optString("supabase_url"),key=config.optString("publishable_key");if(!base.startsWith("https://")||key.isEmpty())throw new IOException("Connect service configuration is unavailable. Local tracking remains available.");
        if(auth&&!signedIn())throw new IOException("Sign in to Connect first.");
        HttpURLConnection c=(HttpURLConnection)new URL(base+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestMethod(method);c.setRequestProperty("apikey",key);c.setRequestProperty("Content-Type","application/json");if(auth)c.setRequestProperty("Authorization","Bearer "+session.optString("access_token"));
        try{if(body!=null){c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}
            int code=c.getResponseCode();if(code==401&&auth&&retry){JSONObject b=obj();put(b,"refresh_token",session.optString("refresh_token"));saveSession((JSONObject)request("/auth/v1/token?grant_type=refresh_token","POST",b,false,false));return request(path,method,body,true,false);}
            String text;try(InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream()){text=in==null?"":new String(readBytes(in),StandardCharsets.UTF_8);}
            if(code<200||code>=300){if(text.contains("40001"))throw new IOException("A record changed on another device. Review the conflict; your queued edit is retained.");throw new IOException(code==429?"Please wait before trying again.":"Request not accepted. Check sign-in, invitation expiry and sharing permission.");}
            return text.isBlank()?JSONObject.NULL:new JSONTokener(text).nextValue();
        }finally{c.disconnect();}
    }
    Object rpc(String name,JSONObject body)throws Exception{return request("/rest/v1/rpc/"+name,"POST",body,true,true);}
    void sendCode(String email)throws Exception{JSONObject b=obj();put(b,"email",email);put(b,"create_user",true);request("/auth/v1/otp","POST",b,false,false);status="Check your email for a sign-in code. Signing in does not upload your records.";}
    void verify(String email,String token)throws Exception{JSONObject b=obj();put(b,"email",email);put(b,"token",token);put(b,"type","email");saveSession((JSONObject)request("/auth/v1/verify","POST",b,false,false));refresh();}
    private JSONArray all(String table)throws Exception{return all(table,"id");}
    private JSONArray all(String table,String order)throws Exception{JSONArray result=new JSONArray();for(int offset=0;;offset+=200){JSONArray next=(JSONArray)request("/rest/v1/"+table+"?select=*&order="+order+"&limit=200&offset="+offset,"GET",null,true,true);for(JSONObject r:rows(next))result.put(r);if(next.length()<200)return result;}}
    void refresh()throws Exception{
        String actor=account();Map<String,JSONObject> cache=new HashMap<>();for(JSONObject r:rows(records))cache.put(r.optString("id"),r);records=new JSONArray();feedback=new JSONArray();
        JSONArray latest=all("cs_connections");String fingerprint=latest.toString();long cursor=recordCursor;if(!fingerprint.equals(connectionFingerprint)||cache.isEmpty()){cursor=0;cache.clear();}
        while(true){JSONArray page=(JSONArray)request("/rest/v1/cs_records?select=*&change_id=gt."+cursor+"&order=change_id&limit=200","GET",null,true,true);for(JSONObject r:rows(page)){cursor=Math.max(cursor,r.optLong("change_id"));if(r.optBoolean("deleted"))cache.remove(r.optString("id"));else cache.put(r.optString("id"),r);}if(page.length()<200)break;}
        Set<String> permitted=new HashSet<>();String after="00000000-0000-0000-0000-000000000000";
        while(true){JSONObject p=obj();put(p,"p_after",after);put(p,"p_limit",200);JSONArray page=(JSONArray)rpc("cs_visible_manifest",p);for(JSONObject r:rows(page)){after=r.getString("id");permitted.add(after);}if(page.length()<200)break;}
        JSONArray people=all("cs_participants","record_id,id"),messages=all("cs_feedback"),confirmations=all("cs_notifications");JSONArray prefs=(JSONArray)request("/rest/v1/cs_notification_preferences?select=*&limit=1","GET",null,true,true);
        if(!actor.equals(account()))return;connections=latest;for(Map.Entry<String,JSONObject> r:cache.entrySet())if(permitted.contains(r.getKey()))records.put(r.getValue());recordCursor=cursor;connectionFingerprint=fingerprint;participants=people;feedback=messages;notifications=confirmations;notificationSettings=prefs.length()==0?obj():prefs.getJSONObject(0);status="Sharing access refreshed.";
    }
    void register(JSONObject p)throws Exception{JSONObject b=obj();put(b,"p_id",p.optString("id"));put(b,"p_name",playerName(p));rpc("cs_register_profile",b);}
    String invite(String role,JSONObject player,String sport,String recipient)throws Exception{register(player);JSONObject b=obj();put(b,"p_role",role);put(b,"p_player",role.equals("player")?player.optString("id"):JSONObject.NULL);put(b,"p_sport",sport);put(b,"p_recipient",recipient);JSONObject r=(JSONObject)rpc("cs_create_invitation",b);return linkHost().isEmpty()?r.getString("code"):"https://"+linkHost()+"/connect/invite#"+r.getString("code");}
    void accept(String input,JSONObject player)throws Exception{String code=ConnectProtocol.code(input,linkHost());if(code==null)throw new IOException("Use the full invitation link or 64-character code.");if(player!=null)register(player);JSONObject b=obj();put(b,"p_code",code);put(b,"p_player",player==null?JSONObject.NULL:player.optString("id"));rpc("cs_accept_invitation",b);context.getSharedPreferences("connect",0).edit().remove("pending").apply();refresh();status="Invitation accepted. Player approval is still required.";}
    String installation(){android.content.SharedPreferences prefs=context.getSharedPreferences("connect",0);String value=prefs.getString("installation","");if(value.isEmpty()){value=id();prefs.edit().putString("installation",value).commit();}return value;}
    void saveNotifications(boolean push,boolean requests,boolean sharing,boolean feedback)throws Exception{JSONObject p=obj();put(p,"p_push",push);put(p,"p_requests",requests);put(p,"p_sharing",sharing);put(p,"p_feedback",feedback);rpc("cs_set_notifications",p);if(push)ConnectPush.enable(context);else{put(p=obj(),"p_installation",installation());rpc("cs_unregister_device",p);ConnectPush.disable(context);}refresh();status="Notification preferences saved. Phone notification permission also applies.";}
    void registerPush(String token){worker.execute(()->{try{if(!signedIn())return;JSONObject p=obj();put(p,"p_installation",installation());put(p,"p_platform","fcm");put(p,"p_token",token);rpc("cs_register_device",p);}catch(Exception e){status="Push registration needs attention. Confirmations remain in Connect.";}});}
    JSONObject preview(String input)throws Exception{JSONObject p=obj();String code=ConnectProtocol.code(input,linkHost());if(code==null)throw new IOException("Use the full invitation link or 64-character code.");put(p,"p_code",code);return (JSONObject)rpc("cs_preview_invitation",p);}
    void decline(String input)throws Exception{preview(input);JSONObject p=obj();put(p,"p_code",ConnectProtocol.code(input,linkHost()));rpc("cs_decline_invitation",p);context.getSharedPreferences("connect",0).edit().remove("pending").apply();status="Invitation declined. Nothing is shared.";}
    void enable(JSONObject player,JSONObject library)throws Exception{register(player);Set<String> allowed=new HashSet<>();JSONArray previous=array(state,"uploadPlayers");for(int n=0;n<previous.length();n++)allowed.add(previous.optString(n));allowed.add(player.optString("id").toLowerCase(Locale.ROOT));put(state,"uploadPlayers",new JSONArray(allowed));persist();sync(library);}
    String linkedPlayer(String remote){return object(state,"linkedPlayers").optString(remote.toLowerCase(Locale.ROOT));}
    void linkPlayer(String remote,String local)throws Exception{JSONObject links=object(state,"linkedPlayers");Iterator<String> keys=links.keys();while(keys.hasNext()){String key=keys.next();if(!local.isEmpty()&&!key.equalsIgnoreCase(remote)&&links.optString(key).equalsIgnoreCase(local))throw new IOException("This local profile is already linked to another online player. Review that link first.");}if(local.isEmpty())links.remove(remote.toLowerCase(Locale.ROOT));else put(links,remote.toLowerCase(Locale.ROOT),local.toLowerCase(Locale.ROOT));put(state,"linkedPlayers",links);persist();status="Local link saved. Both histories remain separate; no records were merged.";}
    boolean isPrivate(String id){return object(state,"privateRecords").optBoolean(id.toLowerCase(Locale.ROOT));}
    void setPrivate(String id,boolean value,JSONObject library)throws Exception{JSONObject values=object(state,"privateRecords");put(values,id.toLowerCase(Locale.ROOT),value);put(state,"privateRecords",values);List<JSONObject> queue=new ArrayList<>(rows(array(state,"queue")));queue.removeIf(q->q.optString("p_id").equalsIgnoreCase(id));put(state,"queue",new JSONArray(queue));persist();for(JSONObject r:rows(records))if(r.optString("id").equalsIgnoreCase(id)){JSONObject p=obj();put(p,"p_id",id);put(p,"p_private",value);put(p,"p_expected",r.optLong("revision"));Object revision=rpc("cs_set_record_private",p);JSONObject revisions=object(state,"revisions");put(revisions,id.toLowerCase(Locale.ROOT),revision);put(state,"revisions",revisions);persist();break;}sync(library);status=value?"Record kept private. Server access removed; saved copies cannot necessarily be erased.":"Record eligible for approved sharing.";}
    void pause()throws Exception{put(state,"uploadPlayers",new JSONArray());put(state,"queue",new JSONArray());persist();status="Uploads paused here. Revoke connections to remove server access.";}
    private boolean allowed(JSONObject r){for(JSONObject c:rows(connections))if(ConnectProtocol.permits(c,r,account()))return true;return false;}
    List<JSONObject> syncConflicts(){List<JSONObject> result=new ArrayList<>();for(JSONObject queued:rows(array(state,"queue")))for(JSONObject remote:rows(records))if(remote.optString("id").equals(queued.optString("p_id"))&&remote.optLong("revision")>queued.optLong("p_expected")){result.add(queued);break;}return result;}
    void resolveConflict(String id,boolean useDevice)throws Exception{JSONObject remote=find(records,id);if(remote==null||!remote.optString("owner_id").equalsIgnoreCase(account()))throw new IOException("Refresh this record before reviewing the conflict.");List<JSONObject> queue=new ArrayList<>(rows(array(state,"queue")));for(int n=0;n<queue.size();n++)if(queue.get(n).optString("p_id").equals(id)){JSONObject queued=queue.get(n),revisions=object(state,"revisions");put(revisions,id,remote.optLong("revision"));if(remote.optBoolean("private")){JSONObject privacy=object(state,"privateRecords");put(privacy,id.toLowerCase(Locale.ROOT),true);put(state,"privateRecords",privacy);put(queued,"p_private",true);JSONObject sporting=copy(queued);sporting.remove("p_expected");sporting.remove("p_operation");sporting.remove("local_hash");put(queued,"local_hash",ConnectProtocol.fingerprint(sporting));}if(useDevice){if(remote.optBoolean("deleted"))throw new IOException("A deleted online record cannot be restored by a queued edit.");put(queued,"p_expected",remote.optLong("revision"));put(queued,"p_operation",id());}else{JSONObject hashes=object(state,"hashes");put(hashes,id,queued.optString("local_hash"));put(state,"hashes",hashes);if(queued.optBoolean("p_deleted")){JSONObject uploaded=object(state,"uploaded");uploaded.remove(id);put(state,"uploaded",uploaded);}queue.remove(n);}put(state,"revisions",revisions);put(state,"queue",new JSONArray(queue));persist();break;}status=useDevice?"Reviewed device version queued. Retry sync to send it with a fresh version check.":"Online version kept. Your local record remains unchanged.";}
    JSONArray pendingFeedback(){return array(state,"feedbackQueue");}
    void queueFeedback(JSONObject request)throws Exception{String text=request.optString("p_text");if(!signedIn()||text.isBlank()||text.codePointCount(0,text.length())>4000)throw new IOException("Enter feedback of up to 4,000 characters.");JSONArray queue=pendingFeedback();queue.put(copy(request));put(state,"feedbackQueue",queue);persist();ConnectSyncJob.schedule(context);status="Feedback saved to the outgoing queue. It will be sent when connected and sharing is still permitted.";}
    void discardFeedback(String id)throws Exception{List<JSONObject> queue=new ArrayList<>(rows(pendingFeedback()));queue.removeIf(r->r.optString("p_id").equals(id));put(state,"feedbackQueue",new JSONArray(queue));persist();status="Queued feedback removed.";}
    private void flushFeedback()throws Exception{while(pendingFeedback().length()>0){JSONObject request=pendingFeedback().getJSONObject(0);rpc("cs_add_feedback",request);JSONArray queue=pendingFeedback();queue.remove(0);put(state,"feedbackQueue",queue);persist();}}
    void sync(JSONObject library)throws Exception{
        if(!signedIn())return;Set<String> players=new HashSet<>();JSONArray ids=array(state,"uploadPlayers");for(int n=0;n<ids.length();n++)players.add(ids.optString(n));
        List<JSONObject> queue=new ArrayList<>(rows(array(state,"queue")));JSONObject hashes=object(state,"hashes"),revisions=object(state,"revisions"),uploaded=object(state,"uploaded");
        List<JSONObject> projected=ConnectProtocol.project(library,players);
        for(JSONObject r:projected){put(r,"p_private",isPrivate(r.optString("p_id")));if(!allowed(r))continue;String id=r.optString("p_id"),hash=ConnectProtocol.fingerprint(r);boolean queued=false;for(JSONObject q:queue)queued|=q.optString("p_id").equals(id);if(hash.equals(hashes.optString(id))||queued)continue;put(r,"p_operation",id());put(r,"p_expected",revisions.optInt(id));put(r,"local_hash",hash);queue.add(r);}
        Set<String> present=new HashSet<>();for(JSONObject r:projected)present.add(r.optString("p_id"));Iterator<String> uploadedIds=uploaded.keys();while(uploadedIds.hasNext()){String rid=uploadedIds.next();JSONObject metadata=object(uploaded,rid);boolean queued=false;for(JSONObject q:queue)queued|=rid.equals(q.optString("p_id"));if(!present.contains(rid)&&players.contains(metadata.optString("p_player"))&&!queued){JSONObject tombstone=copy(metadata);put(tombstone,"p_body",obj());put(tombstone,"p_people",new JSONArray());put(tombstone,"p_deleted",true);put(tombstone,"p_private",true);put(tombstone,"p_operation",id());put(tombstone,"p_expected",revisions.optLong(rid));put(tombstone,"local_hash","deleted");queue.add(tombstone);}}
        put(state,"queue",new JSONArray(queue));persist();refresh();flushFeedback();queue.removeIf(r->!r.optBoolean("p_deleted")&&!allowed(r));put(state,"queue",new JSONArray(queue));persist();
        while(!queue.isEmpty()){JSONObject q=copy(queue.get(0));String hash=q.optString("local_hash"),id=q.optString("p_id");q.remove("local_hash");JSONObject reply=(JSONObject)rpc("cs_put_record",q);put(hashes,id,hash);put(revisions,id,reply.getLong("revision"));if(q.optBoolean("p_deleted"))uploaded.remove(id);else{JSONObject metadata=copy(q);metadata.remove("p_body");metadata.remove("p_people");metadata.remove("p_expected");metadata.remove("p_operation");put(uploaded,id,metadata);}put(state,"uploaded",uploaded);put(state,"hashes",hashes);put(state,"revisions",revisions);queue.remove(0);put(state,"queue",new JSONArray(queue));persist();}
        refresh();status="Permitted sporting records synchronised. Health and media remain on the device.";
        for(JSONObject r:ConnectProtocol.project(library,players)){put(r,"p_private",isPrivate(r.optString("p_id")));if(allowed(r)&&!ConnectProtocol.fingerprint(r).equals(hashes.optString(r.optString("p_id")))){changed(context,library);break;}}
    }
    static void changed(Context c,JSONObject library){if(c.getPackageManager().hasSystemFeature("android.hardware.type.watch"))return;ConnectClient client=get(c);if(!client.signedIn())return;ConnectSyncJob.schedule(c);JSONObject snapshot=copy(library);client.worker.execute(()->{try{client.sync(snapshot);}catch(Exception e){client.status="Sync needs attention. "+e.getMessage();}});}
}
